  for (int seed = 1; seed <= 200 && !found; seed++) {
    srandom(seed);
    runner_start(r, index_of("Loop"));
    runner_step(r);
    found = loop_neighbors_in_use() == 4;
  }
  if (found) {
    for (int f = 0; f < 60; f++) runner_step(r);
